from measure import measure

def validation(m,day,parent,candidate,stage):
 fs=frames(m,day);start=trading_dates(fs,m)[-80];pmet,pnav,pfills,*_=measure(parent,fs,m,start,day);cmet,cnav,cfills,*_=measure(candidate,fs,m,start,day);folder=B/'experiments'/stage;folder.mkdir(parents=True,exist_ok=True);pnav.to_csv(folder/'parent_validation_nav.csv',index=False);cnav.to_csv(folder/'candidate_validation_nav.csv',index=False);pfills.to_csv(folder/'parent_validation_fills.csv',index=False);cfills.to_csv(folder/'candidate_validation_fills.csv',index=False)
 names=[s for s in fs if 'BENCHMARK' not in s];loo=[]
 for s in names:
  rows=rank_ic(candidate,{a:b for a,b in fs.items() if a!=s},day,start);loo.append({'excluded':s,'IC':float(np.mean([r['IC'] for r in rows])) if rows else None})
 pos=sum(r['IC'] is not None and r['IC']>0 for r in loo)/len(loo);checks={'cases':cmet['nonoverlap_blocks']>=12,'net_improvement':np.isfinite(cmet['return_pct']) and np.isfinite(pmet['return_pct']) and cmet['return_pct']>pmet['return_pct'],'risk':cmet['mdd_pct'] is not None and pmet['mdd_pct'] is not None and cmet['mdd_pct']>=pmet['mdd_pct']-3.,'IC':cmet['IC'] is not None and cmet['IC']>0,'stability':pos>=.6,'marks':cmet['missing_nav_marks']==0 and pmet['missing_nav_marks']==0};passed=all(checks.values());status='FORWARD_REQUIRED' if passed else 'REJECTED' if checks['cases'] and checks['marks'] else 'INSUFFICIENT_EVIDENCE';result={'status':status,'cases':cmet['nonoverlap_blocks'],'independent_forward_cases':0,'case_definition':'Nonoverlapfive-sessiontimeblocks, independenceNOTproven','source_asof':str(day)[:10],'checks':checks,'parent':pmet,'candidate':cmet,'leave_one_out':loo,'positive_leaveout_fraction':pos,'isolated_replay_gate_passed':passed,'cause':'PREDICTIVE_OR_COST_WEAKNESS_WITH_CAUSAL_UNCERTAINTY' if not passed else 'HISTORICAL_CONDITIONAL_IMPROVEMENT_REQUIRES_NEW_FORWARD','operating_promotion':'NOT_ELIGIBLE'};freeze(folder/'validation.json',result);return result

